const crypto = require('crypto');
const timestamp = $json.headers?.['x-erp-timestamp'];
const received = $json.headers?.['x-erp-signature'];
const raw = $json.rawBody || JSON.stringify($json.body || {});
if (!timestamp || !received || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) throw new Error('Solicitud vencida o incompleta');
const expected = 'sha256=' + crypto.createHmac('sha256', $env.ERP_RAG_WEBHOOK_SECRET).update(`${timestamp}.${raw}`).digest('hex');
const receivedBuffer = Buffer.from(received);
const expectedBuffer = Buffer.from(expected);
if (receivedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(receivedBuffer, expectedBuffer)) throw new Error('Firma HMAC inválida');
const request = $json.body || {};
if (!request.tenant_id || !request.user_id || !request.message) throw new Error('Solicitud de chat incompleta');
return [{ json: request }];

const request = $('Verificar solicitud ERP').first().json;
const embedding = $json.embedding?.values;
if (!Array.isArray(embedding) || embedding.length !== 768) throw new Error('Embedding de consulta inválido');
return [{ json: { query_embedding: embedding, match_tenant_id: request.tenant_id, match_count: 8, match_threshold: 0.55 } }];

const request = $('Verificar solicitud ERP').first().json;
const found = Array.isArray($json) ? $json : ($json.data || []);
const context = found.slice(0, 8).map((d, index) => `[${index + 1}] ${d.title}: ${d.content}`).join('

') || 'No hay datos empresariales relevantes indexados para esta pregunta.';
const system = `Eres EnterpriseCloud Assistant, un asistente de ERP profesional. Responde en español claro y conciso. Usa exclusivamente el contexto recuperado para datos concretos de la empresa. Si no hay evidencia, dilo y sugiere el módulo ERP pertinente. No inventes cifras, no reveles secretos, no des instrucciones para evadir controles y no ejecutes cambios. La información pertenece a una empresa aislada.

CONTEXTO ERP:
${context}`;
return [{ json: { model: $env.DEEPSEEK_CHAT_MODEL || 'deepseek-chat', temperature: 0.2, max_tokens: 700, messages: [{ role: 'system', content: system }, { role: 'user', content: request.message }], sources: found.map((d) => ({ title: d.title, similarity: d.similarity, source: d.metadata?.source })) } }];
